import Foundation

// The shapes /api/v1 returns, decoded with the field names the server uses. Only the fields
// the app shows are declared; Codable ignores the rest. The bundled fixtures are generated by
// scripts/ios-fixtures.mts from the server's own code, and the unit tests decode them, so a
// field renamed on the server fails a test here rather than on a phone.

struct FixtureChip: Codable, Hashable, Sendable {
    let event: Int
    let opponent: String
    let isHome: Bool
    let difficulty: Int
    let xPts: Double
    let xMins: Int
    let kickoff: String?
    let congested: Bool?
}

struct OtherGame: Codable, Hashable, Sendable {
    let kickoff: String
    let competition: String
    let opponent: String
    let isHome: Bool
}

struct Player: Codable, Hashable, Identifiable, Sendable {
    let id: Int
    let code: Int
    let name: String
    let fullName: String
    let team: String
    let teamId: Int
    let teamName: String
    let pos: String
    let posId: Int
    let cost: Double
    let status: String
    let news: String
    let availability: Int?
    let newsAdded: String?
    let totalPoints: Int
    let form: Double
    let selectedBy: Double
    let xPtsNext: Double
    let xPts: Double
    let xMins: Int
    let startProb: Double
    let fixtures: [FixtureChip]
    let otherGames: [OtherGame]?
}

extension Player {
    /// Whether FPL flags the player, as the website's PlayerFlag decides it. A cleared doubt
    /// leaves the chance at 100 rather than null, and that player is fit.
    var isFlagged: Bool {
        status != "a" || (availability.map { $0 < 100 } ?? false)
    }

    /// When FPL last changed a flagged player's news, the same rule as the website's
    /// `flaggedNewsAdded`. Nil for a fit player: FPL keeps the time after clearing the news.
    var flaggedNewsAdded: Date? {
        isFlagged && !news.isEmpty ? FPLDate.parse(newsAdded) : nil
    }
}

enum Verdict: String, Codable, Sendable {
    case keep, watch, sell
}

struct Replacement: Codable, Hashable, Sendable {
    let player: Player
    let gain: Double
    let reason: String
}

struct PlayerVerdict: Codable, Hashable, Identifiable, Sendable {
    var id: Int { player.id }
    let player: Player
    let verdict: Verdict
    let reason: String
    let replacements: [Replacement]
    let needsHit: Bool
}

struct Suggestion: Codable, Hashable, Identifiable, Sendable {
    var id: Int { player.id }
    let player: Player
    let replaces: Player
    let gain: Double
    let reason: String
}

struct SquadSummary: Codable, Hashable, Sendable {
    let entryId: Int
    let name: String
    let managerName: String?
    let event: Int
    let nextEvent: Int
    let deadline: String?
    let bank: Double
    let freeTransfers: Int
}

struct SquadView: Codable, Sendable {
    let team: SquadSummary
    let verdicts: [PlayerVerdict]
    let suggestions: [Suggestion]
}

struct Swap: Codable, Hashable, Sendable {
    let replaces: Player
    let gain: Double
}

struct WatchedPlayer: Codable, Hashable, Identifiable, Sendable {
    var id: Int { player.id }
    let player: Player
    let swap: Swap?
}

struct WatchlistResponse: Codable, Sendable {
    let players: [WatchedPlayer]
}

// MARK: Matches

struct MatchSide: Codable, Hashable, Sendable {
    let id: Int
    let name: String
    let short: String
    let code: Int
    let score: Int?
}

struct Incident: Codable, Hashable, Sendable {
    let playerId: Int
    let name: String
    let side: String
    let value: Int
}

struct MatchPlayer: Codable, Hashable, Identifiable, Sendable {
    let id: Int
    let code: Int
    let name: String
    let side: String
    let mine: Bool
    let watched: Bool
    let points: Int?
    let minutes: Int?
}

enum MatchStatus: String, Codable, Sendable {
    case upcoming, live, finished, postponed
}

struct Match: Codable, Hashable, Identifiable, Sendable {
    let id: Int
    let event: Int
    let kickoff: String?
    let status: MatchStatus
    let minutes: Int
    let home: MatchSide
    let away: MatchSide
    let goals: [Incident]
    let assists: [Incident]
    let ownGoals: [Incident]
    let penaltiesSaved: [Incident]
    let penaltiesMissed: [Incident]
    let yellowCards: [Incident]
    let redCards: [Incident]
    let bonus: [Incident]
    let bonusProvisional: Bool
    let players: [MatchPlayer]
}

struct MatchDay: Codable, Hashable, Sendable {
    let day: String
    let matches: [Match]
}

struct MatchdayView: Codable, Sendable {
    let event: Int
    let prev: Int?
    let next: Int?
    let live: Bool
    let hasSquad: Bool
    let days: [MatchDay]
}

// MARK: Players

enum PlayerSort: String, Codable, CaseIterable, Identifiable, Sendable {
    case points5, next, form, season, price, picked
    var id: String { rawValue }
    var label: String {
        switch self {
        case .points5: "Points next 5"
        case .next: "Points next game"
        case .form: "Form"
        case .season: "Season points"
        case .price: "Price"
        case .picked: "Most picked"
        }
    }
}

struct BrowseQuery: Codable, Hashable, Sendable {
    var q: String = ""
    var pos: Int? = nil
    var team: Int? = nil
    var maxPrice: Double? = nil
    var sort: PlayerSort = .points5
    var limit: Int = 30
}

struct TeamOption: Codable, Hashable, Identifiable, Sendable {
    let id: Int
    let name: String
    let short: String
}

struct PlayersView: Codable, Sendable {
    let players: [Player]
    let total: Int
    let query: BrowseQuery
    let teams: [TeamOption]
}

struct SavedTeam: Codable, Hashable, Identifiable, Sendable {
    var id: Int { entryId }
    let entryId: Int
    let name: String
    let managerName: String?
}

/// The manager's saved teams and which one My Squad shows (`/api/v1/teams`).
struct TeamsView: Codable, Sendable {
    let active: Int?
    let teams: [SavedTeam]
}

struct Profile: Codable, Sendable {
    let entryId: Int?
}

struct APIErrorBody: Codable, Sendable {
    let error: String
}
